const invoice = $("Crear Cabecera Factura").first().json;
const total = $("Guardia de Presupuesto").first().json.total_factura;

return [{
  json: {
    success: true,
    output: `✅ Factura #${invoice.doc_no} creada exitosamente por un total de ${total}.`,
    invoice_id: invoice.id,
    amount: total
  }
}];

let parsedQuery = {};
try {
  parsedQuery = JSON.parse($input.first().json.query);
} catch (error) {
  throw new Error("El campo 'query' no contiene un JSON válido.");
}

const items = parsedQuery.items || [];
if (items.length === 0) {
  throw new Error("No se enviaron items para facturar en el campo query.");
}

const totalFactura = items.reduce((sum, item) => sum + parseFloat(item.amount), 0);

return [{
  json: {
    ...parsedQuery,
    order_id: $input.first().json.order_id,
    total_factura: totalFactura,
    timestamp: new Date().toISOString()
  }
}];

const saldos = $input.all().map(r => r.json);
const inputOriginal = $("Validar y Calcular Total").first().json;

for (const item of inputOriginal.items) {
  const saldoInfo = saldos.find(s => s.quote_item_id === item.quote_item_id);
  if (saldoInfo && item.amount > (saldoInfo.saldo_disponible + 0.01)) {
    throw new Error(`Exceso de monto: Item ${item.quote_item_id} pide ${item.amount} pero solo quedan ${saldoInfo.saldo_disponible}`);
  }
}

return [inputOriginal];

