const invoiceId = $("Crear Cabecera Factura").first().json.id;
const items = $("Guardia de Presupuesto").first().json.items;

const values = items
  .map((item) => {
    let stepsValue = "";

    if (Array.isArray(item.step_names)) {
      stepsValue = item.step_names.join(", ");
    } else if (typeof item.step_names === "string") {
      stepsValue = item.step_names;
    } else {
      stepsValue = "";
    }

    const safeSteps = stepsValue.replace(/'/g, "''");

    return `(
    ${invoiceId}, 
    (SELECT id FROM order_items WHERE quote_item_id = ${item.quote_item_id} LIMIT 1), 
    1, 
    ${item.amount}, 
    ${item.amount}, 
    ${item.service_id}, 
    ${safeSteps ? `'${safeSteps}'` : "NULL"}
  )`;
  })
  .join(",");

return [
  {
    query: `INSERT INTO invoice_items (invoice_id, order_item_id, quantity, unit_price, total, service_id, steps) VALUES ${values}`,
  },
];
